pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Give the contract some initial Ether
        vm.deal(address(c), 10 ether);

        // Record initial balance of contract
        uint256 initialBalance = address(c).balance;

        // Owner calls sendTo with receiver = contract address itself and amount = 5 ether
        vm.prank(address(this));
        c.sendTo(address(c), 5 ether);

        // After the call, the correct contract (reference) should have the same balance because
        // sending to self doesn't change the contract's balance (transfer to self is a no-op).
        // But the buggy contract does NOT require owner and allows anyone to call, and even 
        // though the receiver is the contract itself, the transfer still reduces the contract's 
        // balance (since it's a self-transfer that actually moves Ether out and then back? 
        // Actually in Solidity, transfer to self does keep balance unchanged).
        // However, the bug differs because the require was removed; but the observable behavior 
        // for this specific scenario: the reference (with require) allows only owner, which is 
        // address(this) in the test, so it succeeds and contract balance stays same (since 
        // self-transfer). The buggy version (without require) also succeeds, but the balance 
        // stays same as well — so this doesn't distinguish.
        // 
        // Let's reconsider: The difference is that non-owner can call. So we need a scenario 
        // where non-owner call causes a difference. But the problem says previous attempts 
        // with non-owner sending to another address were already tried. 
        // 
        // To create a new distinguishing test: Have the owner first send Ether to a non-owner, 
        // then the non-owner calls sendTo with the contract's own Ether? No, the non-owner 
        // doesn't have Ether to send to contract. 
        //
        // Another approach: The reference contract only allows owner to send Ether FROM the 
        // contract. The bug allows anyone to send from contract. So if we deal Ether to the 
        // contract, and then a non-owner calls sendTo with a receiver address, the reference 
        // reverts (no Ether sent), the bug sends Ether. But that's already tried. 
        //
        // Perhaps the subtlety is that the previous tries observed address(this).balance 
        // which is the test contract's balance, not the C contract's balance. So we need 
        // to observe address(c).balance instead. Let's do that: non-owner calls sendTo 
        // to transfer 1 ether to a random address. Reference: revert, so address(c).balance 
        // remains unchanged. Bug: succeeds, so address(c).balance decreases. 
        // That should work and is different from the tried approaches because those observed 
        // address(this).balance (the test contract's balance) not address(c).balance.

        // Let's implement that:
        // Reset state: give contract 10 ether
        vm.deal(address(c), 10 ether);
        uint256 contractBalBefore = address(c).balance;

        // Non-owner (e.g., address(0x123)) tries to send 1 ether to address(0x456)
        address nonOwner = address(0x123);
        address receiver = address(0x456);

        // Non-owner calls sendTo — reference reverts, bug succeeds
        vm.prank(nonOwner);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", receiver, 1 ether));

        // For the reference, ok is false (revert). For the bug, ok is true.
        // We assert that after the call, the contract balance is unchanged (as in reference)
        // This will fail on the bug because the bug sends Ether.
        uint256 contractBalAfter = address(c).balance;
        assertTrue(contractBalAfter == contractBalBefore, "Contract balance should remain unchanged");
    }
}

