pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up non-owner actor
        address nonOwner = address(0x1234);
        address receiver = address(0x5678);
        uint amount = 1 ether;

        // Give nonOwner ether to send
        vm.deal(nonOwner, amount);
        uint receiverBalBefore = receiver.balance;

        // Non-owner tries to call sendTo; reference reverts, bug might not
        vm.prank(nonOwner);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount));

        // If reference: reverts => success == false, receiver balance unchanged
        // If bug: success == true, receiver balance increases by amount
        if (success) {
            // buggy version: send succeeds
            assertEq(receiver.balance, receiverBalBefore + amount);
            // This assert will fail on the reference because success is false, so we never reach here
        } else {
            // reference: revert
            assertEq(receiver.balance, receiverBalBefore);
        }

        // For a single assertion that the reference holds and bug breaks:
        // The reference leaves receiver balance unchanged, bug increases it.
        assertTrue(receiver.balance != receiverBalBefore); // reference: false (unchanged), bug: true (changed)
    }
}

