import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // deploy a non-payable receiver
        NonPayableReceiver receiver = new NonPayableReceiver();

        // fund the owner (which is the test contract, since msg.sender in setUp is this)
        vm.deal(address(this), 1 ether);

        // owner sends 1 wei to receiver; in reference (transfer) it reverts, in buggy (call) it succeeds and burns remaining gas/balance
        bool ok;
        try c.sendTo(address(receiver), 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // in the reference, the call reverts, so address(c).balance remains 1 ether
        // in the buggy, the call doesn't revert, but the fallback reverts causing ether to be lost (contract balance = 0)
        // The observable difference: address(c).balance > 0 in reference, == 0 in bug
        // Check that correct contract leaves balance untouched (i.e. ok is false and balance preserved)
        assertTrue(ok == false && address(c).balance == 1 ether);
    }
}

contract NonPayableReceiver {
    fallback() external {
        revert("I reject ether");
    }
}

