    C c;
    RevertingReceiver receiver;

    function setUp() public {
        c = new C();
        receiver = new RevertingReceiver();
    }

    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        // owner is this contract (address(this)) because we called constructor
        // Actually constructor sets owner = msg.sender, so in setUp() the owner is this contract
        // We'll pre-fund the contract:
        vm.deal(address(c), 1 ether);

        // Prank as owner
        vm.prank(address(c.owner()));
        // Try to send 1 ether to the reverting receiver
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", address(receiver), 1 ether));

        // Reference C would revert, so ok is false; buggy C would not revert, so ok is true
        assertTrue(!ok);
    }
}

